import{_ as i,o as n,c as t,a2 as s}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Zivilisation des intensiven Typs Ostasiens","description":"","frontmatter":{},"headers":[],"relativePath":"de/0031-东亚集约型文明.md","filePath":"de/0031-东亚集约型文明.md"}'),r={name:"de/0031-东亚集约型文明.md"};function a(d,e,l,u,o,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>31</td></tr><tr><td>Modul</td><td>Zivilisationstypologie und Sozialsystem</td></tr><tr><td>Schlüsselwörter</td><td>Intensiv Ostasien, Kollektiv优先, Kultivierung in großem Maßstab, Effiziente Ausführung, Familiäre Erbschaft</td></tr></tbody></table><h2 id="i-ursprung-und-kernphilosophie-der-zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">I. Ursprung und Kernphilosophie der Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#i-ursprung-und-kernphilosophie-der-zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;I. Ursprung und Kernphilosophie der Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h2><p>Die Zivilisation des intensiven Typs Ostasiens ist die am stärksten kollektivistisch gefärbte unter den fünf Typen der symbiotischen Zivilisation, und ihr Ursprung lässt sich auf die jahrtausendealte Zivilisationstradition der ostasiatischen Region in der realen Welt zurückverfolgen. In der ostasiatischen Region haben sich im Laufe der langen historischen Entwicklung zivilisatorische Merkmale herausgebildet, die das Kollektiv in den Mittelpunkt stellen, die Familie als Einheit betrachten und auf Ordnung basieren. Nach der Gründung der symbiotischen Ankerzivilisation wurde diese Tradition mit der symbiotischen Philosophie verbunden, um die einzigartige Zivilisationsform der „Zivilisation des intensiven Typs Ostasiens&quot; zu schaffen.</p><p>Die Kernphilosophie der Zivilisation des intensiven Typs Ostasiens lässt sich in acht Zeichen zusammenfassen: „Kollektiv优先, intensiv und effizient&quot;. Im Einzelnen:</p><ol><li><strong>Kollektiv优先</strong>: In der Beziehung zwischen Individuum und Kollektiv wird betont, dass das Kollektivinteresse über dem individuellen Interesse steht, und die Entwicklung des Individuums sollte in die Entwicklung des Kollektivs integriert werden. Kollektiveinheiten wie Familien, Sekten und Gemeinschaften sind die Grundzellen der Gesellschaft, und das Individuum实现 seinen eigenen Wert, indem es zum Kollektiv beiträgt</li><li><strong>Intensiv und effizient</strong>: Bei der Ressourcenallokation wird betont, dass durch die koordinierte Planung des Kollektivs eine intensive Nutzung und effiziente Allokation von Ressourcen实现 wird. Es wird gegen verteilte, niedrigstufige Wiederholungsbauten opponiert und dafür plädiert, Kräfte zu bündeln, um große Dinge zu vollbringen</li><li><strong>Ordnung und Harmonie</strong>: In den sozialen Beziehungen wird die soziale Ordnung der ehrerbietigen Hierarchie und der altersgemäßen Etikette betont, und das harmonische Zusammenleben zwischen den Menschen wird angestrebt</li><li><strong>Fleiß und Fortschritt</strong>: Bei den individuellen Eigenschaften wird der Geist des Fleißes, der Sparsamkeit, der Ausdauer und des Fortschritts verehrt, und es wird geglaubt, dass durch unermüdliche Anstrengung das Schicksal verändert werden kann</li></ol><p>Diese Philosophien der Zivilisation des intensiven Typs Ostasiens高度 stimmen mit der Kernphilosophie der symbiotischen Ankerzivilisation überein: „mehr Arbeit, mehr Gewinn; sich selbst erzeugen und wachsen; jeder hat einen Weg; gemeinsamer Fortschritt aller Rassen&quot;. Das Kollektiv优先 gewährleistet die Verwirklichung des „gemeinsamen Fortschritts aller Rassen&quot;, das intensive und effiziente gewährleistet die Effizienz von „mehr Arbeit, mehr Gewinn&quot;, und Fleiß und Fortschritt ist die lebendige Manifestation von „sich selbst erzeugen und wachsen&quot;.</p><h2 id="ii-sozialstruktur-der-zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">II. Sozialstruktur der Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#ii-sozialstruktur-der-zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;II. Sozialstruktur der Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h2><p>Die Sozialstruktur der Zivilisation des intensiven Typs Ostasiens nimmt das dreistufige Kollektiv „Familie — Sekte — Gemeinschaft&quot; als Grundrahmen und bildet ein schichtweise verschachteltes und eng verbundenes soziales Netzwerk:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Einheit</th><th>Maßstab</th><th>Kernfunktion</th><th>Methode der Ressourcenallokation</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Familie</td><td>Dutzende bis Hunderte von Personen</td><td>Grundlegende Lebenssicherung, familiäre emotionale Bindung, Anfangsbildung</td><td>Verteilung nach Bedarf innerhalb der Familie</td></tr><tr><td>Zweite Ebene</td><td>Sekte</td><td>Hunderte bis Zehntausende von Personen</td><td>Professionelle Kultivierung, technologische Forschung und Entwicklung, Ressourcenmanagement</td><td>Verteilung nach Arbeit innerhalb der Sekte</td></tr><tr><td>Dritte Ebene</td><td>Gemeinschaft</td><td>Zehntausende bis Hunderttausende von Personen</td><td>Öffentlicher Dienst, grundlegende Infrastruktur, soziale Governance</td><td>Gemeinschaftskoordination + Marktregulierung</td></tr></tbody></table><h3 id="_2-1-familie" tabindex="-1">2.1 Familie <a class="header-anchor" href="#_2-1-familie" aria-label="Permalink to &quot;2.1 Familie&quot;">​</a></h3><p>Die Familie ist die grundlegendste soziale Einheit der Zivilisation des intensiven Typs Ostasiens und besteht normalerweise aus Dutzenden bis Hunderten von blutsverwandten Personen. Die Familie übernimmt die folgenden Kernfunktionen:</p><ul><li><strong>Grundlegende Lebenssicherung</strong>: Die Familienmitglieder helfen sich gegenseitig und stellen sicher, dass die grundlegenden Lebensbedürfnisse jedes Mitglieds erfüllt werden</li><li><strong>Familiäre emotionale Bindung</strong>: Durch Aktivitäten wie Familienrituale und Familientreffen wird die emotionale Bindung zwischen den Mitgliedern aufrechterhalten</li><li><strong>Anfangsbildung</strong>: Die Älteren in der Familie sind für die Anfangsbildung der Jüngeren verantwortlich, einschließlich Grundkenntnisse, Kultivierungseinstieg, moralische Kultivierung usw.</li><li><strong>Ressourcenakkumulation</strong>: Die Familie akkumuliert gemeinsam Reichtum und Kultivierungsressourcen und unterstützt die Entwicklung der Familienmitglieder</li></ul><p>Die Ressourcenallokation innerhalb der Familie folgt dem kombinierten Prinzip von „Verteilung nach Bedarf + Verteilung nach Arbeit&quot; — die grundlegenden Lebensbedürfnisse werden nach Bedarf verteilt, und zusätzliche Kultivierungsressourcen sowie Belohnungen werden nach dem individuellen Beitrag zur Familie verteilt.</p><h3 id="_2-2-sekte" tabindex="-1">2.2 Sekte <a class="header-anchor" href="#_2-2-sekte" aria-label="Permalink to &quot;2.2 Sekte&quot;">​</a></h3><p>Die Sekte ist die Kerneinheit, die für die professionelle Kultivierung und technologische Forschung und Entwicklung in der Zivilisation des intensiven Typs Ostasiens verantwortlich ist, und besteht normalerweise aus Hunderten bis Zehntausenden von Personen mit der gleichen Kultivierungsrichtung oder technologischen Spezialisierung. Die Kernfunktionen der Sekte umfassen:</p><ul><li><strong>Professionelle Kultivierung</strong>: Die Sekte verfügt über ein vollständiges Kultivierungssystem und ein Mentorenteam, das für die systematische professionelle Kultivierung der Jünger verantwortlich ist</li><li><strong>Technologische Forschung und Entwicklung</strong>: Die Sekte bündelt Kräfte, um Forschung und Innovation im Bereich der Kultivierungstechnologie und Ingenieurtechnologie durchzuführen</li><li><strong>Ressourcenmanagement</strong>: Die Sekte erzielt Einnahmen durch das Management von Kultivierungsressourcen, die Bereitstellung technologischer Dienstleistungen usw. und unterstützt den Betrieb und die Entwicklung der Sekte</li><li><strong>Talentoutput</strong>: Die von der Sekte ausgebildeten exzellenten Talente können in höherstufige Institutionen eintreten und zur Entwicklung der Gemeinschaft und der Zivilisation beitragen</li></ul><p>Die Ressourcenallokation innerhalb der Sekte folgt hauptsächlich dem Prinzip der „Verteilung nach Arbeit&quot; — die Jünger erhalten die entsprechende Ressourcenzuteilung basierend auf ihren Kultivierungsergebnissen und ihrem Beitrag zur Sekte. Die Sekte verfügt normalerweise über ein strenges Hierarchiesystem, von äußeren Jüngern, inneren Jüngern, Kernjüngern bis zu Ältesten und Oberhaupt — mit klarer Hierarchie und geordnetem Aufstieg.</p><h3 id="_2-3-gemeinschaft" tabindex="-1">2.3 Gemeinschaft <a class="header-anchor" href="#_2-3-gemeinschaft" aria-label="Permalink to &quot;2.3 Gemeinschaft&quot;">​</a></h3><p>Die Gemeinschaft ist die höchste soziale Einheit in der Zivilisation des intensiven Typs Ostasiens und besteht normalerweise aus Zehntausenden bis Hunderttausenden von Personen, die ein bestimmtes geografisches Gebiet abdecken. Die Kernfunktionen der Gemeinschaft umfassen:</p><ul><li><strong>Öffentlicher Dienst</strong>: Bereitstellung öffentlicher Dienstleistungen wie Bildung, Gesundheit, Wohnen, Umwelt usw.</li><li><strong>Grundlegende Infrastruktur</strong>: Bau und Wartung grundlegender Infrastrukturen wie Anker, Energiekanäle, Verkehrsnetze usw.</li><li><strong>Soziale Governance</strong>: Aufrechterhaltung der sozialen Ordnung, Vermittlung von Streitigkeiten, Durchsetzung von Gesetzen</li><li><strong>Ressourcenkoordination</strong>: Koordination der Kultivierungsressourcen innerhalb des Zuständigkeitsbereichs, Durchführung einer makroskopischen Ressourcenallokation</li></ul><p>Die Ressourcenallokation auf Gemeinschaftsebene folgt dem Prinzip der „Koordination + Markt&quot; — die grundlegenden öffentlichen Ressourcen werden von der Gemeinschaft koordiniert zugewiesen, und die nicht-grundlegenden Ressourcen werden über den Marktmechanismus reguliert.</p><h2 id="iii-kultivierungsmodell-der-zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">III. Kultivierungsmodell der Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#iii-kultivierungsmodell-der-zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;III. Kultivierungsmodell der Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h2><p>Das Kultivierungsmodell der Zivilisation des intensiven Typs Ostasiens zeichnet sich durch „großen Maßstab, Standardisierung und Systematisierung&quot; aus und ist in der Lage, in kurzer Zeit eine große Anzahl qualifizierter Kultivierer auszubilden:</p><h3 id="_3-1-kultivierung-in-großem-maßstab" tabindex="-1">3.1 Kultivierung in großem Maßstab <a class="header-anchor" href="#_3-1-kultivierung-in-großem-maßstab" aria-label="Permalink to &quot;3.1 Kultivierung in großem Maßstab&quot;">​</a></h3><p>Die Zivilisation des intensiven Typs Ostasiens ist gut in der Talentausbildung in großem Maßstab durch das Sektensystem. Eine große Sekte kann gleichzeitig Zehntausende von Jüngern ausbilden, und durch ein standardisiertes Kurssystem und ein fließbandartiges Lehrmodell实现 sie die Produktion von Kultivierungstalenten in großem Maßstab. Die Vorteile dieses Ausbildungsmodells sind hohe Effizienz, breite Abdeckung und die Fähigkeit, das allgemeine Kultivierungsniveau schnell zu verbessern.</p><h3 id="_3-2-standardisiertes-system" tabindex="-1">3.2 Standardisiertes System <a class="header-anchor" href="#_3-2-standardisiertes-system" aria-label="Permalink to &quot;3.2 Standardisiertes System&quot;">​</a></h3><p>Die Zivilisation des intensiven Typs Ostasiens legt Wert auf den standardisierten Aufbau des Kultivierungssystems. Die dreihundert Sätze von Ursprungs-Kultivierungssystemen werden nach ihrer Einführung in die Zivilisation des intensiven Typs Ostasiens normalerweise weiter zu standardisierten Kultivierungslehrmaterialien, Lehrplänen und Bewertungskriterien detailliert ausgearbeitet. Jede Kultivierungsphase hat klare Ziele, Inhalte und Bewertungsmethoden, die die Stabilität der Ausbildungsqualität gewährleisten.</p><h3 id="_3-3-meister-junger-uberlieferung" tabindex="-1">3.3 Meister-Jünger-Überlieferung <a class="header-anchor" href="#_3-3-meister-junger-uberlieferung" aria-label="Permalink to &quot;3.3 Meister-Jünger-Überlieferung&quot;">​</a></h3><p>Obwohl großer Maßstab und Standardisierung betont werden, legt die Zivilisation des intensiven Typs Ostasiens immer noch großen Wert auf die Meister-Jünger-Überlieferung. Jeder Jünger erhält nach dem Eintritt einen Mentor, der für die tägliche Anleitung und moralische Kultivierung des Jüngers verantwortlich ist. Für Jünger mit außergewöhnlichem Talent werden sie sogar als „direkte Jünger&quot; aufgenommen und erhalten eine sorgfältige Eins-zu-Eins-Anleitung durch den Mentor. Diese Kombination aus „großem Maßstab + Personalisierung&quot; gewährleistet nicht nur die Ausbildungseffizienz, sondern berücksichtigt auch die personalisierte Entwicklung der Talente.</p><h3 id="_3-4-bewertung-und-aufstieg" tabindex="-1">3.4 Bewertung und Aufstieg <a class="header-anchor" href="#_3-4-bewertung-und-aufstieg" aria-label="Permalink to &quot;3.4 Bewertung und Aufstieg&quot;">​</a></h3><p>Die Zivilisation des intensiven Typs Ostasiens hat ein strenges Bewertungs- und Aufstiegssystem eingerichtet. Die Jünger müssen regelmäßig an Bewertungen teilnehmen, und der Bewertungsinhalt umfasst Kultivierungsniveau, tatsächliche Kampffähigkeit, theoretisches Wissen, moralische Kultivierung usw. Diejenigen, die die Bewertung bestehen, können im Rang aufsteigen und mehr Ressourcenzuteilung sowie einen höheren Status erhalten; diejenigen, die nicht bestehen, müssen das Jahr wiederholen oder sogar eliminiert werden. Dieses System stimuliert nicht nur den Fortschrittsgeist der Jünger, sondern gewährleistet auch die Qualität der Talentausbildung.</p><h2 id="iv-mechanismus-der-gemeinsamen-vertragsproduktion-der-zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">IV. Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#iv-mechanismus-der-gemeinsamen-vertragsproduktion-der-zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;IV. Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h2><p>Der Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des intensiven Typs Ostasiens nimmt den „Kollektivvertrag&quot; als Hauptform an, was sich deutlich von anderen Typen unterscheidet:</p><ol><li><strong>Vertragseinheit</strong>: Nimmt kollektive Einheiten wie Familien und Sekten als Vertragssubjekte, anstatt Individuen als Vertragssubjekte</li><li><strong>Vertragsinhalt</strong>: Die kollektiven Einheiten übernehmen Aufgaben wie die Entwicklung von Kultivierungsressourcen, die Wartung von Ankern, die technologische Forschung und Entwicklung in bestimmten Gebieten von der Gemeinschaft</li><li><strong>Interne Verteilung</strong>: Nachdem die kollektiven Einheiten die Vertragseinnahmen erhalten haben, erfolgt eine zweite interne Verteilung, die sowohl die kollektive Akkumulation als auch die individuelle Vergütung berücksichtigt</li><li><strong>Gemeinsame Verantwortung</strong>: Die Mitglieder innerhalb der kollektiven Einheiten übernehmen gegenseitig gemeinsame Verantwortung — die hervorragende Leistung einer Person kann dem Kollektiv Belohnungen bringen, und die Regelverletzung einer Person kann auch die Bewertung des Kollektivs beeinflussen</li></ol><p>Die Vorteile dieses Mechanismus des „Kollektivvertrags&quot; bestehen darin, dass er den Skaleneffekt und die Kooperationsvorteile des Kollektivs entfalten und die Effizienz der Ressourcennutzung verbessern kann; gleichzeitig stärkt er auch die Kohäsion des Kollektivs und das Zugehörigkeitsgefühl der Mitglieder.</p><h2 id="v-vorteile-und-herausforderungen-der-zivilisation-des-intensiven-typs-ostasiens" tabindex="-1">V. Vorteile und Herausforderungen der Zivilisation des intensiven Typs Ostasiens <a class="header-anchor" href="#v-vorteile-und-herausforderungen-der-zivilisation-des-intensiven-typs-ostasiens" aria-label="Permalink to &quot;V. Vorteile und Herausforderungen der Zivilisation des intensiven Typs Ostasiens&quot;">​</a></h2><h3 id="_5-1-typische-vorteile" tabindex="-1">5.1 Typische Vorteile <a class="header-anchor" href="#_5-1-typische-vorteile" aria-label="Permalink to &quot;5.1 Typische Vorteile&quot;">​</a></h3><ul><li><strong>Starke Durchsetzungsfähigkeit</strong>: Die kollektivistische Tradition und das strenge Hierarchiesystem gewährleisten, dass Entscheidungen schnell und effizient umgesetzt werden können</li><li><strong>Hohe Effizienz</strong>: Die intensive Ressourcenallokation und die Talentausbildung in großem Maßstab haben eine hohe Entwicklungseffizienz实现</li><li><strong>Starke Kohäsion</strong>: Die enge Verbindung zwischen Familien und Sekten hat eine starke soziale Kohäsion gebildet</li><li><strong>Hohe Stabilität</strong>: Die geordnete Sozialstruktur und die harmonischen zwischenmenschlichen Beziehungen haben die langfristige soziale Stabilität gewährleistet</li></ul><h3 id="_5-2-konfrontierte-herausforderungen" tabindex="-1">5.2 Konfrontierte Herausforderungen <a class="header-anchor" href="#_5-2-konfrontierte-herausforderungen" aria-label="Permalink to &quot;5.2 Konfrontierte Herausforderungen&quot;">​</a></h3><ul><li><strong>Unzureichender individueller Raum</strong>: Die übermäßige Betonung des Kollektivs kann den freien Raum des Individuums einschränken und die Kreativität und Vielfalt des Individuums beeinträchtigen</li><li><strong>Schwacher Innovationsantrieb</strong>: Das standardisierte Ausbildungsmodell kann das innovative Denken einschränken, und es ist notwendig, ein Gleichgewicht zwischen Norm und Innovation zu finden</li><li><strong>Risiko der Hierarchieverfestigung</strong>: Wenn dem strengen Hierarchiesystem ein Mobilitätsmechanismus fehlt, kann dies zu einer Verfestigung der Klassen führen</li><li><strong>Größerer Wettbewerbsdruck</strong>: Der intensive Bewertungs- und Aufstiegsmechanismus kann dem Individuum einen größeren psychologischen Druck bringen</li></ul><p>Angesichts dieser Herausforderungen absorbiert die Zivilisation des intensiven Typs Ostasiens aktiv die Vorteile anderer Typen, wie die Einführung des Innovationsanreizmechanismus des pluralistischen Typs Nordamerikas, des psychologischen Unterstützungssystems des Wohlfahrtstyps Nordeuropas usw., und optimiert kontinuierlich ihr eigenes institutionelles Design.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Zivilisation des intensiven Typs Ostasiens ist der am stärksten kollektivistisch geprägte Zivilisationstyp in der symbiotischen Ankerzivilisation. Mit der Kernphilosophie „Kollektiv优先, intensiv und effizient&quot; hat sie durch die dreistufige Sozialstruktur Familie — Sekte — Gemeinschaft, das groß angelegte standardisierte Kultivierungsmodell und den Mechanismus der gemeinsamen Vertragsproduktion eine effiziente Entwicklung und starke Kohäsion实现. Unter Beibehaltung ihrer eigenen Merkmale absorbiert die Zivilisation des intensiven Typs Ostasiens auch kontinuierlich die Vorteile anderer Typen und entwickelt sich in eine ausgewogenere und inklusivere Richtung.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Überblick über die fünf Typen der symbiotischen Zivilisation)</li><li>36-社会结构与阶层流动 (Sozialstruktur und Klassenmobilität)</li><li>37-共生教育体系 (Symbiotisches Bildungssystem)</li></ul>',46)])])}const m=i(r,[["render",a]]);export{c as __pageData,m as default};
